-- ── 3. Die Casting catalog rows (migration 844): machine_class, where still NULL.
UPDATE process_taxonomy pt
SET machine_class = v.machine_class
FROM (VALUES
  ($str$Cleaning$str$, $str$die_casting_cleaning$str$),
  ($str$Coremaking$str$, $str$die_casting_coremaking$str$),
  ($str$Core Refractory Coat$str$, $str$die_casting_core_refractory_coat$str$),
  ($str$Finishing$str$, $str$die_casting_finishing$str$),
  ($str$Gravity Die Casting$str$, $str$die_casting_gravity_die_casting$str$),
  ($str$High Pressure Die Casting$str$, $str$die_casting_high_pressure_die_casting$str$),
  ($str$Melting$str$, $str$die_casting_melting$str$),
  ($str$Refractory Coat Air Dry$str$, $str$die_casting_refractory_coat_air_dry$str$),
  ($str$Refractory Coat Oven Dry$str$, $str$die_casting_refractory_coat_oven_dry$str$),
  ($str$Trim$str$, $str$die_casting_trim$str$),
  ($str$Visual Inspection$str$, $str$die_casting_visual_inspection$str$)
) AS v(process_name, machine_class)
WHERE pt.process_group = 'Die Casting' AND pt.process_name = v.process_name AND pt.machine_class IS NULL;

UPDATE process_calculator_mappings pcm
SET machine_class = v.machine_class, updated_at = now()
FROM (VALUES
  ($str$Cleaning$str$, $str$die_casting_cleaning$str$),
  ($str$Coremaking$str$, $str$die_casting_coremaking$str$),
  ($str$Core Refractory Coat$str$, $str$die_casting_core_refractory_coat$str$),
  ($str$Finishing$str$, $str$die_casting_finishing$str$),
  ($str$Gravity Die Casting$str$, $str$die_casting_gravity_die_casting$str$),
  ($str$High Pressure Die Casting$str$, $str$die_casting_high_pressure_die_casting$str$),
  ($str$Melting$str$, $str$die_casting_melting$str$),
  ($str$Refractory Coat Air Dry$str$, $str$die_casting_refractory_coat_air_dry$str$),
  ($str$Refractory Coat Oven Dry$str$, $str$die_casting_refractory_coat_oven_dry$str$),
  ($str$Trim$str$, $str$die_casting_trim$str$),
  ($str$Visual Inspection$str$, $str$die_casting_visual_inspection$str$)
) AS v(operation, machine_class)
WHERE pcm.process_group = 'Die Casting' AND pcm.operation = v.operation AND pcm.machine_class IS NULL;

NOTIFY pgrst, 'reload schema';

